Вот функция на JavaScript, которая проверяет, является ли какое-либо из 5 чисел простым числом и выводит это число на консоль, если оно является простым:

```javascript
function checkPrime(arr) {
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];
    if (isPrime(num)) {
      console.log(num);
      break; // выходим из цикла, если нашли первое простое число
    }
  }
}

function isPrime(num) {
  if (num <= 1) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(num); i++) {
    if (num % I === 0) {
      return false;
    }
  }
  return true;
}

// Пример использования
const arr = [2, 7, 15, 19, 23];
checkPrime(arr); // Выведет 7 на консоль
```

Функция `checkPrime` проходит по массиву и для каждого числа вызывает функцию `isPrime`, которая проверяет, является ли число простым. Если число простое, то функция `checkPrime` выводит его на консоль и завершает цикл, т. К. Проверяет только первое найденное простое число. 

Функция `isPrime` проверяет, является ли число простым, в соответствии с простейшей проверкой на простоту - проверкой на делители от 2 до квадрата числа. 

